import Vue from 'vue';
import { Component, Emit, Prop } from 'vue-property-decorator';
import { IGigCategory, IGigGame } from '../../types';

@Component({
    name: 'GameList'
})
export default class GameList extends Vue {
    @Prop({
        required: true,
        type: Array
    })
    public games: Array<IGigCategory>;

    @Prop({
        required: true,
        type: String
    })
    public deviceType: string;

    @Prop({
        required: true,
        type: String
    })
    public orientation: string;

    @Prop({
        required: true,
        type: String
    })
    public displayMode: string;

    @Prop({
        required: true,
        type: Boolean
    })
    public visible: boolean;

    @Emit('onOpenGame')
    public onOpenGame(game: IGigGame) {
        return game;
    }
}
